package com.bank.savepoint.db;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Mimics JDBC savepoint semantics over an in-memory ledger.
public class BatchConnection {
    private static final Logger log = Logger.getLogger(BatchConnection.class.getName());
    private final Map<String, BigDecimal> committed = new HashMap<>();
    private Map<String, BigDecimal> pending = new HashMap<>();
    private final Map<String, Map<String, BigDecimal>> savepoints = new HashMap<>();
    private final Set<String> frozen;

    public BatchConnection(Map<String, BigDecimal> seed, Set<String> frozen) {
        committed.putAll(seed); pending.putAll(seed); this.frozen = frozen;
    }

    public void savepoint(String name) {
        savepoints.put(name, new HashMap<>(pending));     // snapshot current pending state
        log.fine(() -> "SAVEPOINT " + name);
    }

    public void credit(String id, BigDecimal amt) {
        if (frozen.contains(id)) throw new IllegalStateException("account frozen: " + id);
        pending.merge(id, amt, BigDecimal::add);
    }

    public void rollbackTo(String name) {
        pending = new HashMap<>(savepoints.get(name));    // rewind only to the savepoint
        log.warning(() -> "ROLLBACK TO " + name);
    }

    public void commit() { committed.clear(); committed.putAll(pending); log.info("COMMIT"); }
    public BigDecimal balance(String id) { return committed.get(id); }
}
