package com.bank.savepoint.service;

import com.bank.savepoint.db.BatchConnection;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class SalaryBatchService {
    private static final Logger log = Logger.getLogger(SalaryBatchService.class.getName());

    // Process all records in ONE transaction; skip bad ones via savepoints.
    public List<String> runBatch(BatchConnection conn, List<String> employeeIds, BigDecimal salary) {
        List<String> skipped = new ArrayList<>();
        for (String id : employeeIds) {
            String sp = "sp_" + id;
            conn.savepoint(sp);                    // bookmark before this record
            try {
                conn.credit(id, salary);
                log.info(() -> "credited " + id + " Rs." + salary);
            } catch (RuntimeException ex) {
                conn.rollbackTo(sp);               // undo ONLY this record
                skipped.add(id);
                log.log(Level.SEVERE, "skipped " + id + ": " + ex.getMessage());
            }
        }
        conn.commit();                             // commit all good credits at once
        return skipped;
    }
}
