package com.bank.savepoint;

import com.bank.savepoint.db.BatchConnection;
import com.bank.savepoint.service.SalaryBatchService;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class SavepointDemo {
    private static final Logger log = Logger.getLogger(SavepointDemo.class.getName());

    public static void main(String[] args) {
        setupLogger();
        Map<String, BigDecimal> seed = new HashMap<>();
        seed.put("EMP001", new BigDecimal("50000"));
        seed.put("EMP057", new BigDecimal("0"));
        seed.put("EMP058", new BigDecimal("30000"));
        BatchConnection conn = new BatchConnection(seed, Set.of("EMP057"));

        SalaryBatchService svc = new SalaryBatchService();
        List<String> skipped = svc.runBatch(conn,
                List.of("EMP001","EMP057","EMP058"), new BigDecimal("80000"));

        log.info("skipped=" + skipped);
        log.info("EMP001=" + conn.balance("EMP001"));
        log.info("EMP057=" + conn.balance("EMP057") + " (unchanged, frozen)");
        log.info("EMP058=" + conn.balance("EMP058"));
    }

    private static void setupLogger() {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
